INSERT INTO public.college_evidence (college_id, field_key, claim_summary, source_name, source_url, checked_at, confidence_score, verification_status, extraction_method)
SELECT colleges.id, imported.field_key, imported.claim_summary, imported.source_name, imported.source_url, '2026-09-21T00:00:00+05:45'::timestamptz, imported.confidence_score::smallint, 'pending', 'structured_import'
FROM imported
JOIN public.colleges ON colleges.slug = imported.college_slug
ON CONFLICT (college_id, field_key, source_url) WHERE superseded_at IS NULL DO NOTHING;

-- Excluded from the college evidence ledger: 6. Budhanilkantha School; 41. National School of Sciences; 57. Rato Bangala School; 65. Select School below to Apply; 67. Siddhartha Vanasthali Institute; 78. Ullens School.
